marks = 75

if marks >= 90:
    grade = "A"
elif marks >= 75:
    grade = "B"
elif marks >= 60:
    grade = "C"
elif marks >= 40:
    grade = "D"
else:
    grade = "F"

print(f"Grade: {grade}")   # Grade: B

# Ternary (one-liner)
result = "Pass" if marks >= 40 else "Fail"

age    = 20
has_id = True

if age >= 18:
    if has_id:
        print("Entry allowed")
    else:
        print("Show ID")
else:
    print("Under age")

# range
for i in range(1, 6):
    print(i, end=" ")      # 1 2 3 4 5

# enumerate
fruits = ["apple", "banana", "cherry"]
for idx, val in enumerate(fruits, start=1):
    print(f"{idx}. {val}")

# dict iteration
student = {"name": "Alice", "age": 21}
for key, value in student.items():
    print(f"{key}: {value}")

# while loop
n = 1
while n <= 5:
    print(n, end=" ")   # 1 2 3 4 5
    n += 1

# break — stop at first even
for n in range(1, 10):
    if n % 2 == 0:
        print("First even:", n)   # 2
        break

# continue — skip odds
evens = []
for n in range(1, 11):
    if n % 2 != 0:
        continue
    evens.append(n)
print(evens)   # [2, 4, 6, 8, 10]

# for-else
for n in range(2, 10):
    if 10 % n == 0:
        print("Factor:", n)
        break
else:
    print("10 is prime")   # won't print
